def try_admit(key, rule):
    lease = pool.get(key)
    if lease and lease.tokens > 0 and lease.expires > now():
        lease.tokens -= 1
        if lease.tokens < LOW_WATER: refill_async(key, rule)
        return True
    granted = redis.take(rule, key, n=batch_size(rule))
    if granted == 0: return False
    pool.put(key, Lease(tokens=granted - 1, expires=now() + 1.0))
    return True

def check(ctx):
    try:
        return redis_client.take(rules, key, timeout_ms=5)
    except (Timeout, BreakerOpen, RedisError):
        metrics.inc('ratelimit.fail_open')
        return local_bucket(key, rate=rule.rate / fleet_size()).take()
